cat > /app/polyglot/main.rs <<'EOF'
//\
fn main() {
//\
    let n: u64 = std::env::args()
//\
        .nth(1)
//\
        .and_then(|s| s.parse().ok())
//\
        .unwrap_or(0);
//\
    let mut a: u64 = 1;
//\
    let mut b: u64 = 1;
//\
    for _ in 0..n {
//\
        let t = a.wrapping_add(b);
//\
        a = b;
//\
        b = t;
//\
    }
//\
    println!("{}", a);
//\
}
/*
C++ only from this point on.
/*/
