    unsigned long long n = argc > 1 ? std::strtoull(argv[1], nullptr, 10) : 0;
    unsigned long long a = 1, b = 1;
    for (unsigned long long i = 0; i < n; ++i) {
        unsigned long long t = a + b;
        a = b;
        b = t;
    }
    std::cout << a << '\n';
    return 0;
}
//\
